mapper.select:
select coalesce(sum(o.pay_amount), 0)
from oms_order o
where 
  and o.create_time >= #{startTime}
  and o.create_time < #{endTime}

select count(1)
from oms_order o
where 
  and o.create_time >= #{startTime}
  and o.create_time < #{endTime}

select count(distinct coalesce(o.member_id, o.member_username, o.order_sn))
from oms_order o
where o.create_time >= #{startTime}

select count(1)
from oms_order o
where o.create_time >= #{startTime}
  and o.create_time < #{endTime}
